insert into pb_ai.eval_runs(run, fn, label, k, ids, cases) select '1121-lib7e-r9', 'ai-next', 'lib7e round 9 (fresh) + extras', (o - 1)::int, array(select x->>'id' from jsonb_array_elements(e) x), e from jsonb_array_elements($j$[[{"id":"st7-01","q":"At what depth do I need shoring or a trench box?","where":"Spokane, WA","level":"pipelayer"},{"id":"st7-04","q":"What CO reading on the gas meter is too high for a manhole entry?","where":"Fresno, CA","level":"foreman"},{"id":"st7-06","q":"What is the minimum wage I have to pay a new laborer?","where":"Savannah, GA","level":"office"}],[{"id":"st7-08","q":"At what depth do I need shoring or a trench box?","where":"Phoenix, AZ","level":"pipelayer"},{"id":"st7-11","q":"At what depth do I need shoring or a trench box?","where":"Oakland, CA","level":"pipelayer"},{"id":"st7-12","q":"What is the minimum wage for laborers on our job?","where":"Seattle, WA","level":"office"}],[{"id":"fu7-04-t1","q":"How do I set up hydraulic shores in an 8 foot trench in Type C soil?","where":"Denver, CO","level":"foreman"},{"id":"fu7-20-t1","q":"How do I pick a trench box for a 12 foot deep sewer trench?","where":"Nashville, TN","level":"foreman"}]]$j$::jsonb) with ordinality t(e, o);
insert into pb_ai.eval_runs(run, fn, label, k, ids, cases) with s as (select *, (row_number() over (order by id) - 1) / 3 g from pb_ai.eval_set where id = any(array['lib-in-dig-1','lib-in-dig-3','lib-al-dig-3','lib-nm-dig-3','lib-az-dig-2','lib-al-dig-4','lib-nv-dig-1','lib-nh-dig-2','lib-nh-dig-3','lib-al-dig-2','lib-ny-dig-3','lib-ny-dig-2','lib-nv-dig-4','lib-ny-dig-1','lib-nv-dig-2','lib-ky-sp-1','lib-ky-sp-3','lib-or-sp-2','lib-or-sp-12','lib-or-sp-6','lib-wa-sp-13','lib-wa-sp-15','lib-wa-sp-14','lib-ca-sp-15','lib-ca-sp-4','lib-ca-sp-17','lib-mi-sp-6','lib-id-tc-1','lib-az-tc-2','lib-az-tc-3','lib-ky-tc-2','lib-us-mutcd-32','lib-ne-tc-1','lib-us-mutcd-12','lib-us-mutcd-42','lib-nd-tc-1','lib-co-tc-1','lib-pa-tc-2','lib-md-tc-1','lib-us-mutcd-24','lib-ok-tc-1','lib-tx-tc-2','lib-us-fed-26','lib-ca-row-1','lib-us-em-1','lib-us-em-2','lib-us-osha-1','lib-us-osha-42','lib-wa-fup-1','lib-us-osha-48','lib-us-osha-55','lib-us-mutcd-54','lib-us-fed-11','lib-us-fed-19','tr3','cs1','pm1','nw13','em1','ng2','nw1','nw14','sa1','gn1','lib-us-mutcd-40','lib-us-mutcd-55','lib-us-osha-62','lib-il-dig-4','lib-wa-fup-5','lib-ms-tc-1','lib-oh-tc-1','lib-la-dig-1','lib-mi-dig-1','lib-or-tc-1','lib-wa-sp-3','lib-us-dig-3','lib-ut-dig-1','lib-la-dig-3','lib-or-sp-4','lib-or-sp-7','lib-nd-dig-3','lib-us-mutcd-52','lib-wv-dig-3','lib-ri-dig-1','lib-al-tc-1','lib-fl-dig-2','lib-oh-dig-4','lib-ut-tc-1','lib-mo-tc-1','lib-or-sp-10','lib-ok-dig-3','lib-tx-dig-2','lib-oh-tc-2','lib-sd-dig-1','lib-oh-dig-2','lib-co-dig-2','lib-us-mutcd-37','lib-ky-dig-1','lib-us-mutcd-48','lib-or-sp-11','lib-us-mutcd-22','lib-or-tc-3','lib-ca-sp-11','lib-pa-dig-2','lib-nd-dig-1']))
  select '1121-lib7e-r9', 'ai-next', 'lib7e round 9 (fresh) + extras', 1000 + g, array_agg(id), jsonb_agg(jsonb_build_object('id', id, 'q', q, 'where', "where", 'level', level)
      || case when images is null then '{}'::jsonb else jsonb_build_object('images', images) end
      || case when image_ids is null then '{}'::jsonb else jsonb_build_object('image_ids', to_jsonb(image_ids)) end
      || case when feature is null then '{}'::jsonb else jsonb_build_object('feature', feature) end
      || case when model is null then '{}'::jsonb else jsonb_build_object('model', model) end) from s group by g;
select pb_ai.eval_pump('1121-lib7e-r9') started, (select count(*) from pb_ai.eval_runs where run = '1121-lib7e-r9') batches;
